// static
bool StructTraits<::arc::mojom::VideoFrame::DataView, ::arc::mojom::VideoFramePtr>::Read(
    ::arc::mojom::VideoFrame::DataView input,
    ::arc::mojom::VideoFramePtr* output) {
  bool success = true;
  ::arc::mojom::VideoFramePtr result(::arc::mojom::VideoFrame::New());
  
      if (success)
        result->id = input.id();
      if (success)
        result->handle_fd = input.TakeHandleFd();
      if (success && !input.ReadCodedSize(&result->coded_size))
        success = false;
      if (success && !input.ReadFormat(&result->format))
        success = false;
      if (success && !input.ReadPlanes(&result->planes))
        success = false;
      if (success)
        result->modifier = input.modifier();
  *output = std::move(result);
  return success;
}

